import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>Cem kilobytes é o tamanho de arquivo mais útil da internet. É pequeno o suficiente para qualquer formulário de envio e grande o suficiente para ficar bonito.</p>\n<p>Currículos, portais de emprego, miniaturas de blog e gráficos de e-mail vivem bem com 100 KB. É o tamanho onde qualidade e praticidade se encontram.</p>\n<p>Este guia explica por que 100 KB ganhou essa fama, como a compressão chega até ele e como conseguir o resultado mais nítido possível.</p>\n<h2 id=\"why-100kb-is-the-sweet-spot\">Por que 100 KB é o tamanho ideal</h2>\n<p>A maioria dos formulários de envio limita os arquivos entre 50 KB e 500 KB. Um arquivo de 100 KB passa em quase todos sem pensar duas vezes.</p>\n<p>Ao mesmo tempo, 100 KB guardam dados suficientes para uma foto ficar limpa. Os rostos continuam naturais, o texto continua legível e as cores continuam lisas.</p>\n<p>O número também é gentil com conexões lentas. Uma imagem de 100 KB carrega em uma fração de segundo, mesmo com um sinal fraco de celular.</p>\n<p>Essa combinação é rara. Tamanhos menores ficam piores, tamanhos maiores são rejeitados com mais frequência, e 100 KB acerta no meio.</p>\n<h2 id=\"what-fits-in-100kb\">O que cabe com folga em 100 KB?</h2>\n<p>Um retrato cabe fácil. Um retrato em dimensões normais de web mantém os detalhes com 100 KB, incluindo cabelo, óculos e textura da roupa.</p>\n<p>As miniaturas de blog também cabem. Uma imagem de destaque de 1200 pixels de largura com 100 KB fica nítida em qualquer tela onde ela de fato aparecer.</p>\n<p>As capturas de tela ficam confortáveis com 100 KB também. O texto da interface continua legível, que é a primeira coisa a falhar em tamanhos menores.</p>\n<p>Só imagens muito detalhadas sofrem. Um infográfico denso ou uma paisagem larga com folhas finas pode precisar de 200 KB para ficar nítido.</p>\n<h2 id=\"how-the-100kb-tool-works\">Como funciona a ferramenta de 100 KB</h2>\n<p>A <a href=\"/pt/comprimir-imagem-para-100kb/\">ferramenta Comprimir imagem para 100 KB</a> roda toda no seu navegador. Sua imagem nunca é enviada para um servidor.</p>\n<p>Ela procura sozinha a melhor qualidade. A ferramenta testa níveis de qualidade, se aproximando do ajuste mais alto que ainda fique abaixo de 100 KB.</p>\n<p>A qualidade vem primeiro. A ferramenta só reduz as dimensões em pixels quando baixar a qualidade sozinha não atinge o alvo.</p>\n<p>Entradas de até 25 MB são aceitas, incluindo arquivos JPG, PNG, WebP e HEIC. Uma foto de celular direto da câmera funciona bem.</p>\n<h2 id=\"quality-at-100kb\">Qualidade da imagem com 100 KB</h2>\n<p>A maioria das pessoas não consegue distinguir uma foto de 100 KB da original. As diferenças só aparecem quando você dá zoom de perto.</p>\n<p>Os tons de pele são o melhor teste. Com 100 KB, eles ficam lisos e naturais, sem as manchas que aparecem com 50 KB.</p>\n<p>As bordas nítidas também se mantêm. Armações de óculos, joias e texto impresso mantêm a definição nesse tamanho.</p>\n<p>Os fundos são o único lugar para ficar de olho. Um céu em gradiente liso pode mostrar faixas sutis, embora sejam discretas com 100 KB.</p>\n<h2 id=\"jpg-vs-png-vs-webp-100kb\">JPG vs PNG vs WebP com 100 KB</h2>\n<p>O JPG é a escolha padrão para fotos com 100 KB. É aceito em todo lugar e lida bem com tons lisos.</p>\n<p>O WebP costuma produzir um resultado um pouco mais limpo no mesmo tamanho. O problema é a compatibilidade: alguns portais e sistemas mais antigos rejeitam arquivos WebP.</p>\n<p>O PNG serve para gráficos, não para fotos. Um logotipo ou gráfico com cores chapadas fica nítido em PNG, mas uma foto em PNG desperdiça o orçamento.</p>\n<p>A ferramenta pode converter automaticamente PNGs grandes para JPG ou WebP. Essa única opção muitas vezes transforma uma compressão que falhou num acerto limpo.</p>\n<h2 id=\"resumes-and-job-portals\">Currículos e portais de emprego</h2>\n<p>Os portais de emprego são o motivo mais comum para as pessoas precisarem de 100 KB. Uma foto de currículo, uma amostra de portfólio ou um certificado escaneado enfrentam o mesmo teto.</p>\n<p>Um retrato com 100 KB parece profissional. Os recrutadores veem um rosto claro, não um quadrado pixelado, o que importa mais do que as pessoas admitem.</p>\n<p>Os certificados escaneados precisam de cuidado. O texto impresso pequeno precisa continuar legível, então veja a prévia do resultado e dê zoom antes de enviar.</p>\n<p>Se o portal aceitar WebP, use-o para fotos. Se ele só listar JPG, fique com JPG e deixe a busca de qualidade fazer o trabalho.</p>\n<h2 id=\"websites-and-blogs\">Sites e blogs</h2>\n<p>As miniaturas de blog com 100 KB carregam rápido e ficam nítidas. Uma página com dez miniaturas pesa cerca de 1 MB, o que a maioria das conexões aguenta fácil.</p>\n<p>Os mecanismos de busca premiam páginas rápidas. As imagens costumam ser a parte mais pesada de uma página, então mantê-las perto de 100 KB ajuda direto no tempo de carregamento.</p>\n<p>As imagens principais podem ser maiores, mas as de apoio raramente precisam. Uma imagem de apoio de 100 KB é invisível em termos de qualidade para a maioria dos leitores.</p>\n<p>Para uma otimização completa da página, combine a ferramenta de 100 KB com o <a href=\"/pt/otimizar-imagens-para-web/\">Otimizador de imagens para web</a>, que adiciona predefinições e HTML pronto para colar.</p>\n<h2 id=\"email-and-newsletters\">E-mail e newsletters</h2>\n<p>Os clientes de e-mail demoram para renderizar imagens pesadas. Um gráfico de 100 KB aparece quase na hora na caixa de entrada, enquanto um de 2 MB pode travar.</p>\n<p>As newsletters com várias imagens são as que mais ganham. Cinco imagens com 100 KB somam 500 KB, o que mantém o e-mail inteiro leve.</p>\n<p>Mantenha o formato simples para e-mail. O JPG é a escolha mais segura, pois alguns clientes de e-mail lidam mal com WebP.</p>\n<p>Teste sempre o e-mail enviando para você mesmo primeiro. Confira se as imagens carregam rápido e se nada parece esticado ou borrado.</p>\n<h2 id=\"batch-compression\">Comprimindo muitas imagens para 100 KB</h2>\n<p>Você pode comprimir uma pasta inteira de imagens para 100 KB num só lote. Solte todas, e cada uma é processada com o mesmo alvo.</p>\n<p>Os resultados baixam juntos como um arquivo ZIP. Isso mantém um conjunto de miniaturas ou fotos de portfólio organizado num só lugar.</p>\n<p>O modo em lote é ideal para migrações de blog. Converter cinquenta miniaturas antigas uma por uma levaria uma tarde; um lote leva minutos.</p>\n<p>Confira alguns resultados antes de baixar o ZIP inteiro. Se uma imagem parecer suave, ajuste o formato dela e rode só aquele arquivo de novo.</p>\n<h2 id=\"common-mistakes\">Erros comuns com 100 KB</h2>\n<p>Começar de um arquivo já comprimido é o maior erro. Cada rodada de compressão adiciona dano, então use sempre o original.</p>\n<p>Travar o formato em PNG para uma foto é outro erro. O PNG não consegue chegar a 100 KB com limpeza em fotos detalhadas, e a ferramenta vai avisar.</p>\n<p>Esquecer de conferir o resultado também é comum. O tamanho do arquivo pode estar certo enquanto a imagem está borrada, então veja a prévia antes de baixar.</p>\n<p>Por fim, não presuma que todo portal aceita WebP. Confira primeiro os formatos aceitos, ou você pode acabar comprimindo duas vezes.</p>\n<h2 id=\"when-100kb-is-not-enough\">Quando 100 KB não bastam</h2>\n<p>Imagens grandes e detalhadas às vezes precisam de mais espaço. Um infográfico largo com rótulos minúsculos pode continuar borrado com 100 KB.</p>\n<p>Trabalhos de impressão também precisam de mais. Uma foto destinada ao papel deve ficar em alta resolução, e 100 KB é um tamanho de web, não de impressão.</p>\n<p>Nesses casos, suba para o <a href=\"/pt/comprimir-imagem-para-200kb/\">compressor de 200 KB</a> ou o <a href=\"/pt/comprimir-imagem-para-500kb/\">compressor de 500 KB</a>.</p>\n<p>A regra continua a mesma: use o maior tamanho que a sua situação permitir. A qualidade vale os kilobytes extras quando eles estão disponíveis.</p>\n<h2 id=\"under-100kb-badge\">O selo Abaixo de 100 KB e o que ele garante</h2>\n<p>Quando a compressão dá certo, a ferramenta mostra um selo Abaixo de 100 KB. Esse selo significa que o arquivo final ficou abaixo de 100 KB em bytes exatos.</p>\n<p>A medição exata em bytes importa porque os portais conferem bytes, não números arredondados. Um arquivo que seu celular chama de 100 KB pode ser na verdade 100,4 KB.</p>\n<p>A ferramenta mira um pouco abaixo da linha, geralmente ficando entre 98 KB e 99,9 KB. Essa margem protege você de diferenças de arredondamento.</p>\n<p>Se o selo não aparecer, o arquivo errou o alvo. A ferramenta diz isso com honestidade em vez de entregar um arquivo que será rejeitado.</p>\n<p>Nunca envie um arquivo sem o selo. Uma nova tentativa rápida com outro formato vale muito mais que um envio rejeitado.</p>\n<h2 id=\"dimension-scaling-100kb\">Como funciona o redimensionamento com 100 KB</h2>\n<p>O redimensionamento reduz o tamanho em pixels da sua imagem quando só os cortes de qualidade não chegam a 100 KB. Ele acontece em passos pequenos, não num salto só.</p>\n<p>A ferramenta testa escalas como 90%, 80% e menores, parando na primeira que couber. Cada passo mantém o máximo de tamanho possível.</p>\n<p>Um passo pequeno de escala costuma ser invisível. Uma foto mostrada com 800 pixels de largura parece idêntica com 720 pixels de largura.</p>\n<p>O redimensionamento ajuda mais com originais muito grandes. Uma foto de 4000 pixels de largura tem muito mais pixels que qualquer tela precisa, então aparar não custa nada visível.</p>\n<p>Você também pode travar as dimensões se um portal exigir pixels exatos. A ferramenta então vai trabalhar mais na qualidade sozinha e pode avisar se o alvo não puder ser atingido.</p>\n<h2 id=\"social-media-100kb\">100 KB para redes sociais e avatares</h2>\n<p>As redes sociais comprimem seus envios de novo, então começar com 100 KB dá a elas um arquivo limpo para trabalhar. Um original enorme muitas vezes volta pior.</p>\n<p>As fotos de perfil são o melhor caso. Um retrato de 100 KB envia na hora e sobrevive à compressão da própria plataforma com os detalhes intactos.</p>\n<p>As imagens de capa precisam de mais cuidado. Elas são exibidas grandes, então confira o resultado em tamanho cheio antes de enviá-la como banner.</p>\n<p>Para publicações com texto por cima, veja o texto de perto. A compressão da plataforma suaviza letras pequenas, então comece do arquivo de 100 KB mais nítido que conseguir fazer.</p>\n<p>Lembre-se de que cada plataforma tem seus próprios limites. Confira antes de comprimir, pois um arquivo feito para uma plataforma pode não servir para outra.</p>\n<h2 id=\"storing-100kb-files\">Organizando seus arquivos de 100 KB</h2>\n<p>Guarde os arquivos comprimidos em pastas por função. Uma pasta para candidaturas e outra para imagens de blog evitam misturas.</p>\n<p>Dê nome aos arquivos incluindo o tamanho. Um nome como retrato-100kb.jpg diz na hora para que serve o arquivo.</p>\n<p>Guarde sempre os originais numa pasta separada. As cópias comprimidas são descartáveis; os originais, não.</p>\n<p>Revise os arquivos guardados antes de reutilizá-los. Um arquivo feito há um ano pode não seguir as exigências atuais do portal para o qual você está se candidatando.</p>\n<p>Na dúvida, comprima de novo a partir do original. Leva um minuto, e o resultado vai seguir exatamente as regras de hoje.</p>\n<h2 id=\"when-to-move-up\">Quando subir para 200 KB</h2>\n<p>Algumas imagens precisam de mais que 100 KB. Paisagens largas, infográficos densos e fotos detalhadas de produto ganham com o espaço extra.</p>\n<p>O sinal é a suavidade visível. Se o texto borrar ou a textura fina sumir com 100 KB, a imagem está pedindo um orçamento maior.</p>\n<p>A impressão é outro motivo para subir. Um arquivo de 100 KB é um tamanho de web; qualquer coisa destinada ao papel deve ficar bem maior.</p>\n<p>Confira primeiro o destino. Se o portal ou a plataforma permitir 200 KB, use o <a href=\"/pt/comprimir-imagem-para-200kb/\">compressor de 200 KB</a> em vez de brigar com o limite de 100 KB.</p>\n<p>O objetivo é sempre o mesmo: o maior tamanho que a sua situação permitir, com a melhor qualidade que esse tamanho aguentar.</p>\n<h2 id=\"image-weight-budgets\">Orçamentos de peso de imagem para páginas inteiras</h2>\n<p>Uma única imagem de 100 KB é leve, mas as páginas carregam muitas imagens. Dez miniaturas com 100 KB pesam 1 MB juntas, o que é um orçamento sensato para uma página.</p>\n<p>Defina um orçamento total antes de começar. Uma postagem de blog com oito imagens cabe bem abaixo de 1 MB quando cada imagem fica perto de 100 KB.</p>\n<p>Priorize a imagem principal. Dê 200 KB a ela se merecer, e mantenha as imagens de apoio com 100 KB ou menos.</p>\n<p>Meça o peso real da página depois de publicar. As ferramentas de desenvolvedor do navegador mostram o total, e o número costuma surpreender.</p>\n<p>Uma página que carrega rápido mantém os leitores. O peso das imagens costuma ser o maior fator, e 100 KB por imagem é uma regra prática confiável.</p>\n<h2 id=\"retina-screens\">Imagens de 100 KB em telas Retina e de alta densidade</h2>\n<p>As telas Retina concentram mais pixels no mesmo tamanho físico. Uma imagem nítida numa tela normal pode parecer suave numa tela Retina.</p>\n<p>O conserto é servir uma imagem com o dobro da largura do tamanho de exibição. Uma miniatura mostrada com 400 pixels de largura deve ter 800 pixels no arquivo.</p>\n<p>Com 100 KB, uma imagem de 800 pixels continua limpa. Os pixels extras custam peso de arquivo, mas a busca binária equilibra a qualidade com o orçamento.</p>\n<p>Para miniaturas pequenas, isso importa pouco. Para imagens de destaque grandes, a diferença entre um arquivo padrão e um pronto para Retina é visível.</p>\n<p>Teste numa tela real de alta densidade quando puder. Capturas de tela do resultado escondem justamente a suavidade que você está tentando conferir.</p>\n<h2 id=\"seasonal-content\">Conteúdo sazonal e reutilização de imagens de 100 KB</h2>\n<p>As imagens de blog são reutilizadas entre as estações. Uma miniatura de 100 KB feita para uma postagem pode reaparecer num resumo, numa newsletter e num cartão social.</p>\n<p>Guarde o arquivo comprimido junto com a postagem a que ele pertence. Uma pasta compartilhada de miniaturas facilita a reutilização e evita compressões duplicadas.</p>\n<p>Confira a imagem antes de cada reutilização. Uma miniatura que parecia boa no ano passado pode não servir para o layout ou o corte deste ano.</p>\n<p>Nunca comprima de novo um arquivo reutilizado. Se precisar de um novo tamanho, volte ao original e comprima de novo.</p>\n<p>Uma boa organização transforma imagens de 100 KB em recursos reutilizáveis. Um pouco de disciplina nos nomes agora economiza horas de retrabalho depois.</p>\n<p>Para os passos práticos, leia <a href=\"/pt/blog/como-reduzir-imagem-para-100kb/\">Como reduzir uma imagem para 100 KB</a>. Para uma comparação de qualidade formato por formato, veja <a href=\"/pt/blog/qualidade-de-imagem-100kb-jpg-png-webp/\">Qualidade de imagem com 100 KB: JPG vs PNG vs WebP</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"100 KB bastam para uma foto de perfil profissional?","answer":"Sim. Um retrato com 100 KB fica limpo e profissional no LinkedIn, em portais de emprego e em sites de empresas. Rostos, cabelo e roupa mantêm os detalhes nesse tamanho, e o arquivo passa em quase todos os limites de envio."},{"question":"Posso comprimir uma foto de 10 MB para 100 KB?","answer":"Sim, a ferramenta aceita entradas de até 25 MB e pode reduzir uma foto de 10 MB para menos de 100 KB. A busca binária encontra a melhor qualidade que couber, e o redimensionamento entra se só a qualidade não bastar. Espere alguma suavização em fotos muito detalhadas."},{"question":"Comprimir para 100 KB vai remover o fundo da minha foto?","answer":"Não. A compressão só reduz o tamanho do arquivo; ela não edita o conteúdo da imagem. Se você precisar remover o fundo, use primeiro a ferramenta de remoção de fundo e depois comprima o resultado para 100 KB."},{"question":"Por que minha captura de tela em PNG ficou maior depois de comprimir para 100 KB?","answer":"Um arquivo pode crescer quando é recodificado num formato inadequado para ele, e a ferramenta avisa quando isso acontece. Trocar a saída para JPG ou WebP costuma resolver, pois esses formatos lidam com fotos e capturas de tela de forma bem mais eficiente que o PNG."},{"question":"A ferramenta de 100 KB funciona sem internet?","answer":"A compressão em si roda localmente no seu navegador depois que a página carrega, então nenhum envio acontece. Você ainda precisa carregar a página primeiro, o que exige conexão com a internet."},{"question":"Como sei se minha imagem está mesmo abaixo de 100 KB?","answer":"A ferramenta mostra o tamanho do resultado e uma confirmação Abaixo de 100 KB. Você também pode conferir o arquivo baixado no seu aparelho, onde ele deve ficar um pouco abaixo de 100 KB, geralmente entre 98 e 99,9 KB."}];
